{"success": true, "name": "sop-wiki-build", "file": "scripts/sop_wiki_builder_v3.py", "content": "#!/usr/bin/env python3
"""
SOP Stage C: Wiki Builder v3
三次专项 LLM 调用：
  Call 1 - 提取 + 语义去重（只做判断，不写内容）
  Call 2×N - 逐页独立生成（每页专注，有上下文）
  Call 3 - 图谱连通性审查（补 wikilink）
"""
import argparse, json, os, re, sys, urllib.request
from datetime import datetime, timezone
from pathlib import Path

# ── 公用函数 ──────────────────────────────────────────────────────────────────

def call_llm(prompt: str, max_tokens: int = 8000) -> tuple:
    """返回 (text, prompt_tokens, completion_tokens)"""
    provider = os.environ.get("WIKI_LLM_PROVIDER", "gemini")
    if provider == "gemini":
        return _call_gemini(prompt, max_tokens)
    if provider == "deepseek":
        return _call_deepseek(prompt, max_tokens)
    raise ValueError(f"unsupported WIKI_LLM_PROVIDER: {provider}")


def _call_gemini(prompt: str, max_tokens: int) -> tuple:
    api_key = os.environ.get("GOOGLE_CLOUD_API_KEY", "")
    if not api_key:
        raise RuntimeError("GOOGLE_CLOUD_API_KEY not set")
    model = os.environ.get("WIKI_GEMINI_MODEL", "gemini-2.5-flash-lite")
    payload = json.dumps({
        "contents": [{"role": "user", "parts": [{"text": prompt}]}],
        "generationConfig": {
            "temperature": 0.2,
            "topP": 0.8,
            "topK": 40,
            "maxOutputTokens": max_tokens,
        },
    }).encode()
    url = (f"https://aiplatform.googleapis.com/v1/publishers/google/models"
           f"/{model}:generateContent?key={api_key}")
    req = urllib.request.Request(url, data=payload, headers={"Content-Type": "application/json"})
    # Retry up to 3 times for transient API issues
    for attempt in range(3):
        try:
            with urllib.request.urlopen(req, timeout=120) as resp:
                data = json.loads(resp.read())
        except (urllib.error.HTTPError, urllib.error.URLError, json.JSONDecodeError) as e:
            if attempt < 2:
                time.sleep(3 * (attempt + 1))
                continue
            raise RuntimeError(f"Gemini API call failed after 3 attempts: {e}")
        candidate = data["candidates"][0]
        parts = candidate.get("content", {}).get("parts", [])
        if parts:
            break
        # Empty candidate — transient Gemini issue, retry
        import time
        if attempt < 2:
            print(f"  ⚠️ Gemini returned empty candidate (attempt {attempt+1}), retrying...")
            time.sleep(5 * (attempt + 1))
        else:
            raise RuntimeError(
                f"Gemini returned empty candidate after 3 attempts. "
                f"finishReason={candidate.get('finishReason','')}, "
                f"blockedReason={candidate.get('blockedReason','')}, "
                f"Response keys: {sorted(data.keys())}"
            )
    reason = candidate.get("finishReason", "UNKNOWN")
    content = candidate.get("content", {})
    parts = content.get("parts", [])
    if not parts:
        # Log full response for debugging then try blocked-reason fallback
        fr = candidate.get("finishReason", "")
        br = candidate.get("blockedReason", "")
        pr = candidate.get("promptFeedback", {}).get("blockReason", "")
        raise RuntimeError(
            f"Gemini response has empty/missing 'parts' — finishReason={fr}, "
            f"blockedReason={br}, promptBlockReason={pr}. "
            f"Response keys: {sorted(data.keys())}"
        )
    # Try text from first part; fallback to later parts if first is a thought
    text = ""
    for p in parts:
        if "text" in p and p["text"].strip():
            text = p["text"]
            break
    if not text:
        raise RuntimeError(
            f"Gemini response has parts but no text content. "
            f"part keys: {[list(p.keys()) for p in parts]}, "
            f"finishReason={reason}"
        )
    usage = data.get("usageMetadata", {})
    pt = usage.get("promptTokenCount", 0)
    ct = usage.get("candidatesTokenCount", 0)
    return text, pt, ct


def _call_deepseek(prompt: str, max_tokens: int) -> tuple:
    """Call DeepSeek API with OpenAI-compatible chat completions endpoint."""
    import time
    api_key = os.environ.get("DEEPSEEK_API_KEY", "")
    if not api_key:
        raise RuntimeError("DEEPSEEK_API_KEY not set (source ~/.hermes/.env)")
    model = os.environ.get("WIKI_DEEPSEEK_MODEL", "deepseek-v4-flash")
    payload = json.dumps({
        "model": model,
        "messages": [{"role": "user", "content": prompt}],
        "max_tokens": max_tokens,
        "temperature": 0.2,
    }).encode()
    url = "https://api.deepseek.com/v1/chat/completions"
    req = urllib.request.Request(url, data=payload,
        headers={"Content-Type": "application/json", "Authorization": f"Bearer {api_key}"})
    for attempt in range(3):
        try:
            with urllib.request.urlopen(req, timeout=120) as resp:
                data = json.loads(resp.read())
        except (urllib.error.HTTPError, urllib.error.URLError, json.JSONDecodeError) as e:
            if attempt < 2:
                time.sleep(3 * (attempt + 1))
                continue
            raise RuntimeError(f"DeepSeek API call failed after 3 attempts: {e}")
        content = data["choices"][0]["message"]["content"]
        if content and content.strip():
            break
        # Empty content — retry
        if attempt < 2:
            print(f"  ⚠️ DeepSeek returned empty content (attempt {attempt+1}), retrying...")
            time.sleep(5 * (attempt + 1))
        else:
            raise RuntimeError(
                f"DeepSeek returned empty content after 3 attempts. "
                f"Response keys: {sorted(data.keys())}"
            )
    usage = data.get("usage", {})
    pt = usage.get("prompt_tokens", 0)
    ct = usage.get("completion_tokens", 0)
    return content, pt, ct


def extract_json(text: str) -> dict:
    """从 LLM 输出中提取 JSON（兼容 ```json ... ``` 包裹）"""
    text = re.sub(r"```json\s*", "", text)
    text = re.sub(r"```\s*", "", text)
    # Find the outermost JSON object or array
    brace_start = text.find("{")
    bracket_start = text.find("[")

    start = -1
    if brace_start != -1 and (bracket_start == -1 or brace_start < bracket_start):
        start = brace_start
        brace = "{"
        close = "}"
    elif bracket_start != -1:
        start = bracket_start
        brace = "["
        close = "]"

    if start == -1:
        raise ValueError(f"No JSON found in response: {text[:200]}")

    depth = 0
    end = -1
    for i, c in enumerate(text[start:], start):
        if c == brace:
            depth += 1
        elif c == close:
            depth -= 1
        if depth == 0:
            end = i + 1
            break

    if end == -1:
        raise ValueError(
            f"Incomplete JSON: found opening {brace} at {start} but no matching {close} "
            f"after {len(text)-start} chars. First 200 chars: {text[start:start+200]}"
        )

    json_str = text[start:end]
    # Try parsing, if it fails, attempt to 'repair' by appending missing closing braces or brackets
    try:
        return json.loads(json_str)
    except json.JSONDecodeError as e:
        print(f"  ⚠️ JSON decode failed, attempting to repair: {e}")
        repaired_json_str = json_str

        # If the error is about unterminated string or unexpected end, try to complete the structure
        if "Unexpected end of data" in str(e) or "Unterminated string" in str(e):
            # Add missing closing braces/brackets based on the outermost type
            if brace == "{":
                repaired_json_str += "}"
            elif brace == "[":
                repaired_json_str += "]"

        # Always try to close an open string if there's an odd number of quotes
        # This is a bit more speculative, but can help with malformed LLM output
        if repaired_json_str.count('"') % 2 != 0: # If odd number of quotes
             repaired_json_str += '"'

        # If still an odd number of quotes after adding one, it means there's an internal unclosed string.
        # Try to find the last unescaped quote and add a closing quote after it.
        if repaired_json_str.count('"') % 2 != 0:
            last_quote_idx = -1
            for i in range(len(repaired_json_str) - 1, -1, -1):
                # Check for unescaped quote
                if repaired_json_str[i] == '"' and (i == 0 or repaired_json_str[i-1] != '\\'):
                    last_quote_idx = i
                    break
            if last_quote_idx != -1:
                repaired_json_str = repaired_json_str[:last_quote_idx+1] + '"' + repaired_json_str[last_quote_idx+1:]


        # After all attempts to repair, try parsing again
        try:
            print(f"  尝试修复JSON: '{repaired_json_str[:200]}...'")
            return json.loads(repaired_json_str)
        except json.JSONDecodeError as repair_e:
            raise ValueError(
                f"Failed to decode JSON even after repair attempt: {repair_e}. "
                f"Original JSON string: {json_str[:500]}...\n"
                f"Repaired JSON string: {repaired_json_str[:500]}..."
            ) from repair_e
        raise ValueError(f"Failed to decode JSON: {e}. JSON string: {json_str[:500]}") from e


def slugify(name: str) -> str:
    name = re.sub(r'[<>:"/\\|?*]', '-', name)
    name = re.sub(r'-+', '-', name).strip('-')
    return name[:80]


def read_existing_wiki(wiki_path: Path) -> str:
    """读取现有 wiki 页面清单（供去重用）"""
    lines = []
    for subdir in ["sources", "entities", "concepts"]:
        d = wiki_path / "wiki" / subdir
        if not d.exists():
            continue
        for f in d.glob("*.md"):
            if f.name == ".gitkeep":
                continue
            content = f.read_text(encoding="utf-8")
            title_m = re.search(r'^title:\s*["\']?(.+?)["\']?\s*$', content, re.M)
            title = title_m.group(1) if title_m else f.stem
            lines.append(f"- [{subdir}] {title} → {f.name}")
    return "\n".join(lines) if lines else "（暂无已有页面）"


def today() -> str:
    return datetime.now(timezone.utc).strftime("%Y-%m-%d")


