        current_json_str = initial_json_str

        # 1. Basic cleaning: remove trailing commas, newlines, spaces
        current_json_str = current_json_str.rstrip(",\n\r ")

        # 2. Balance quotes (if an odd number, add one at the end)
        if current_json_str.count('"') % 2 != 0:
            current_json_str += '"'

        # 3. Balance braces and brackets
        brace_balance = current_json_str.count('{') - current_json_str.count('}')
        bracket_balance = current_json_str.count('[') - current_json_str.count(']')

        current_json_str += '}' * max(0, brace_balance)
        current_json_str += ']' * max(0, bracket_balance)

        try:
            return json.loads(current_json_str)
        except json.JSONDecodeError as e:
            print(f"  ⚠️ JSON repair attempt {attempt+1} failed: {e}")
            # If still failing, shorten the string slightly for the next attempt
            # This is a heuristic to handle internal truncation or malformation
            initial_json_str = initial_json_str[:-1]
            if len(initial_json_str) < 2: # Stop if string gets too short
                break

    raise ValueError(
        f"Could not extract or repair complete JSON after {max_repair_attempts} attempts. "
        f"Starting from: {text[start_idx:start_idx+500]}..."
    )


def slugify(name: str) -> str:
    name = re.sub(r'[<>:"/\\|?*]', '-', name)
    name = re.sub(r'-+', '-', name).strip('-')
    return name[:80]


def read_existing_wiki(wiki_path: Path) -> str:
    """读取现有 wiki 页面清单（供去重用）"""
    lines = []
    for subdir in ["sources", "entities", "concepts"]:
        d = wiki_path / "wiki" / subdir
        if not d.exists():
            continue
        for f in d.glob("*.md"):
            if f.name == ".gitkeep":
                continue
            content = f.read_text(encoding="utf-8")
            title_m = re.search(r'^title:\s*["\']?(.+?)["\']?\s*$', content, re.M)
            title = title_m.group(1) if title_m else f.stem
            lines.append(f"- [{subdir}] {title} → {f.name}")
    return "\n".join(lines) if lines else "（暂无已有页面）"


