def extract_json(text: str) -> dict:
    """从 LLM 输出中提取 JSON（兼容 ```json ... ``` 包裹），并尝试修复不完整的 JSON。"""
    text = re.sub(r"```json\s*", "", text)
    text = re.sub(r"```\s*", "", text)

    best_json = None
    best_len = -1

    for start_idx in [m.start() for m in re.finditer(re.escape("{"), text)]:
            open_count = 0
            end_idx = -1
            current_close_char = "}"

            for i, char in enumerate(text[start_idx:]):
                if char == start_char:
                    open_count += 1
                elif char == current_close_char:
                    open_count -= 1

                if open_count == 0:
                    end_idx = start_idx + i + 1
                    break

            # If a balanced block is found or we just take a chunk to the end
            json_candidate_raw = text[start_idx:end_idx] if end_idx != -1 else text[start_idx:]

            # Attempt repair
            repaired_json_str = json_candidate_raw

            # 1. Balance quotes (if an odd number, add one at the end)
            if repaired_json_str.count('"') % 2 != 0:
                repaired_json_str += '"'

            # 2. Add missing closing braces/brackets if unbalanced
            brace_diff = repaired_json_str.count('{') - repaired_json_str.count('}')
            bracket_diff = repaired_json_str.count('[') - repaired_json_str.count(']')

            if brace_diff > 0:
                repaired_json_str += '}' * brace_diff
            if bracket_diff > 0:
                repaired_json_str += ']' * bracket_diff

            # 3. Remove trailing commas if present before closing brace/bracket
            repaired_json_str = re.sub(r",\s*([}\]])", r"\1", repaired_json_str)

            try:
                parsed_json = json.loads(repaired_json_str)
                if len(repaired_json_str) > best_len:
                    best_json = parsed_json
                    best_len = len(repaired_json_str)
            except json.JSONDecodeError:
                pass # Continue to next candidate or repair

    if best_json is not None:
        return best_json
    else:
        raise ValueError(f"Could not extract or repair complete JSON from text starting with: {text[:500]}...")


def slugify(name: str) -> str:
    name = re.sub(r'[<>:"/\\|?*]', '-', name)
    name = re.sub(r'-+', '-', name).strip('-')
