import argparse, json, os, re, sys, urllib.request, time
from datetime import datetime, timezone
from pathlib import Path

# ── 公用函数 ──────────────────────────────────────────────────────────────────

def call_llm(prompt: str, max_tokens: int = 8000) -> tuple:
    """返回 (text, prompt_tokens, completion_tokens)"""
    provider = os.environ.get("WIKI_LLM_PROVIDER", "gemini")
    if provider == "gemini":
        return _call_gemini(prompt, max_tokens)
    if provider == "deepseek":
        return _call_deepseek(prompt, max_tokens)
    raise ValueError(f"unsupported WIKI_LLM_PROVIDER: {provider}")


def _call_gemini(prompt: str, max_tokens: int) -> tuple:

    api_key = os.environ.get("GOOGLE_CLOUD_API_KEY", "")
    if not api_key:
        raise RuntimeError("GOOGLE_CLOUD_API_KEY not set")
    model = os.environ.get("WIKI_GEMINI_MODEL", "gemini-2.5-flash-lite")
    payload = json.dumps({
        "contents": [{"role": "user", "parts": [{"text": prompt}]}],
        "generationConfig": {
            "temperature": 0.2,
            "topP": 0.8,
            "topK": 40,
            "maxOutputTokens": max_tokens,
        },
    }).encode()
    url = (f"https://aiplatform.googleapis.com/v1/publishers/google/models"
           f"/{model}:generateContent?key={api_key}")
    req = urllib.request.Request(url, data=payload, headers={"Content-Type": "application/json"})
    # Retry up to 3 times for transient API issues
    for attempt in range(3):
        try:
            with urllib.request.urlopen(req, timeout=120) as resp:
                data = json.loads(resp.read())
        except (urllib.error.HTTPError, urllib.error.URLError, json.JSONDecodeError) as e:
            if attempt < 2:
                time.sleep(3 * (attempt + 1))
                continue
            raise RuntimeError(f"Gemini API call failed after 3 attempts: {e}")
        candidate = data["candidates"][0]
        parts = candidate.get("content", {}).get("parts", [])
        if parts:
            break
        # Empty candidate — transient Gemini issue, retry

        if attempt < 2:
            print(f"  ⚠️ Gemini returned empty candidate (attempt {attempt+1}), retrying...")
            time.sleep(5 * (attempt + 1))
        else:
            raise RuntimeError(
                f"Gemini returned empty candidate after 3 attempts. "
                f"finishReason={candidate.get('finishReason','')}, "
                f"blockedReason={candidate.get('blockedReason','')}, "
                f"Response keys: {sorted(data.keys())}"
            )
    reason = candidate.get("finishReason", "UNKNOWN")
    content = candidate.get("content", {})
    parts = content.get("parts", [])
    if not parts:
        # Log full response for debugging then try blocked-reason fallback
        fr = candidate.get("finishReason", "")
        br = candidate.get("blockedReason", "")
        pr = candidate.get("promptFeedback", {}).get("blockReason", "")
        raise RuntimeError(
            f"Gemini response has empty/missing 'parts' — finishReason={fr}, "
            f"blockedReason={br}, promptBlockReason={pr}. "
            f"Response keys: {sorted(data.keys())}"
        )
    # Try text from first part; fallback to later parts if first is a thought
    text = ""
    for p in parts:
        if "text" in p and p["text"].strip():
            text = p["text"]
            break
    if not text:
        raise RuntimeError(
            f"Gemini response has parts but no text content. "
            f"part keys: {[list(p.keys()) for p in parts]}, "
            f"finishReason={reason}"
        )
    usage = data.get("usageMetadata", {})
    pt = usage.get("promptTokenCount", 0)
    ct = usage.get("candidatesTokenCount", 0)
    return text, pt, ct


