            end = i + 1
            break

    json_str_candidate = text[start_idx:end] if end != -1 else text[start_idx:]

    try:
        parsed_json = json.loads(json_str_candidate)
        if not isinstance(parsed_json, dict):
            raise ValueError("Extracted JSON is not an object as expected.")
        return parsed_json
    except json.JSONDecodeError as e:
        print(f"  ⚠️ JSON decode failed on initial attempt, attempting repair: {e}")
        repaired_json_str = json_str_candidate

        # Heuristic repair attempts:
