        # 2. Add missing closing braces/brackets
        brace_diff = repaired_json_str.count('{') - repaired_json_str.count('}')
        bracket_diff = repaired_json_str.count('[') - repaired_json_str.count(']') # Should be 0 if only object

        if brace_diff > 0:
            repaired_json_str += '}' * brace_diff
        # If there are stray open brackets, close them too, though unlikely for manifest
        if bracket_diff > 0:
            repaired_json_str += ']' * bracket_diff

        # 3. Remove trailing commas if present before closing brace/bracket
        repaired_json_str = re.sub(r",\s*([}\]])", r"\1", repaired_json_str)

        try:
            print(f"  尝试修复JSON (第2次): '{repaired_json_str[:200]}...'")
            parsed_json = json.loads(repaired_json_str)
            if not isinstance(parsed_json, dict):
                raise ValueError("Repaired JSON is not an object as expected.")
            return parsed_json
        except json.JSONDecodeError as repair_e:
            raise ValueError(
                f"Failed to decode JSON even after repair attempt: {repair_e}. "
                f"Original JSON string (from start_idx): {json_str_candidate[:500]}...\n"
                f"Repaired JSON string: {repaired_json_str[:500]}..."
            ) from repair_e


def slugify(name: str) -> str:
    name = re.sub(r'[<>:"/\\|?*]', '-', name)
    name = re.sub(r'-+', '-', name).strip('-')
    return name[:80]


def read_existing_wiki(wiki_path: Path) -> str:
    """读取现有 wiki 页面清单（供去重用）"""
    lines = []
    for subdir in ["sources", "entities", "concepts"]:
        d = wiki_path / "wiki" / subdir
        if not d.exists():
            continue
        for f in d.glob("*.md"):
            if f.name == ".gitkeep":
                continue
            content = f.read_text(encoding="utf-8")
            title_m = re.search(r'^title:\s*["\']?(.+?)["\']?\s*$', content, re.M)
            title = title_m.group(1) if title_m else f.stem
            lines.append(f"- [{subdir}] {title} → {f.name}")
    return "\n".join(lines) if lines else "（暂无已有页面）"


def today() -> str:
    return datetime.now(timezone.utc).strftime("%Y-%m-%d")


# ── Call 1：提取 + 去重 ────────────────────────────────────────────────────────

EXTRACT_PROMPT = """你是知识图谱分析专家。从以下视频分析报告中提取所有实体和概念，并与现有 wiki 清单做语义去重。

## 现有 wiki 页面（去重参考）
{existing_wiki}

## 分析报告
{report}

## 任务
1. 提取所有值得建页的实体（人物/组织/产品/工具/平台）和概念（技术概念/方法论/架构思想）
2. 对每项判断：new=新建 / merge=合并到已有页（语义相同）/ skip=太泛不值得建页
3. 实体和概念各自去重（同一事物只保留一个规范名称）

## 命名规范（严格遵守）
- **实体 slug**：专有名词/产品/品牌/人名/工具名 → 保持英文原名，用连字符，如 `hermes-agent`、`claude`、`openai`
- **概念 slug**：技术概念/机制/模式/架构思想 → 必须使用中文，如 `自进化机制`、`双向链接`、`三层记忆架构`
- 所有 slug 不含空格，中文概念直接用汉字，不需要拼音

## 输出格式（严格 JSON，不要任何注释）
{{
  "source": {{
    "title": "源页面中文标题",
    "slug": "中文标题slug，直接用汉字+连字符"
  }},
  "entities": [
    {{"name": "规范名称（专有名词保持英文）", "slug": "英文连字符slug", "action": "new|merge|skip", "merge_target": "已有文件名或null", "reason": "一句话"}}
  ],
  "concepts": [
    {{"name": "中文概念名", "slug": "中文slug（必须汉字）", "action": "new|merge|skip", "merge_target": "已有文件名或null", "reason": "一句话"}}
  ]
}}"""


def call1_extract(report_content: str, existing_wiki: str) -> dict:
    print("  [Call 1] 提取+去重...")
    prompt = EXTRACT_PROMPT.format(existing_wiki=existing_wiki, report=report_content[:6000])
    text, pt, ct = call_llm(prompt, max_tokens=8000)
    result = extract_json(text)
    print(f"    → entities: {len(result.get('entities',[]))} 条, concepts: {len(result.get('concepts',[]))} 条 | tokens: {pt}+{ct}")
    return result, pt, ct


# ── Call 2：逐页生成 ──────────────────────────────────────────────────────────

SOURCE_PROMPT = """生成一个 wiki Source 页面（Markdown）。

## TheSchema 要求
- frontmatter 必须包含：title, type(=source), tags, summary, sources, created, updated, layer(=L1), run_id
- 正文：执行摘要 + 核心要点（≥300汉字）+ 至少2个 [[wikilink]]

## 报告内容（节选）
{report}

## 该 Source 页的基本信息
- title: {title}
- slug: {slug}
- run_id: {run_id}
- sources 字段值: raw/notebooklm-analysis/{analysis_file}

## 已知的相关实体/概念页（用于 wikilink）
{related_pages}

直接输出完整 Markdown，不要用 ``` 代码块包裹，不要任何解释。"""

ENTITY_PROMPT = """生成一个 wiki Entity 页面（Markdown）。

## TheSchema 要求
- frontmatter：title, type(=entity), tags, summary, sources, created, updated, layer(=L1), confidence(=high), reasoning
- 正文：实体描述（≥200汉字）+ 在本视频中的角色 + 至少2个 [[wikilink]]
- sources 字段必须是数组格式：["raw/notebooklm-analysis/{analysis_file}"]（直接使用此精确文件名，禁止修改）

## 实体信息
- name: {name}
- 来源报告: {analysis_file}
- 来源报告节选（与该实体相关的段落）:
{excerpt}

## 已知的相关页面（用于 wikilink）
{related_pages}

直接输出完整 Markdown，不要用 ``` 代码块包裹，不要任何解释。"""

CONCEPT_PROMPT = """生成一个 wiki Concept 页面（Markdown）。

## TheSchema 要求
- frontmatter：title, type(=concept), tags, summary, sources, created, updated, layer(=L1), confidence(=high), reasoning("直接从NotebookLM思维导图中提取的概念。")
- 正文：概念定义（≥200汉字）+ 技术细节 + 应用场景 + 至少2个 [[wikilink]]
- sources 字段必须是数组格式：["raw/notebooklm-analysis/{analysis_file}"]（直接使用此精确文件名，禁止修改）

## 概念信息
- name: {name}
- 来源报告: {analysis_file}
- 来源报告节选（与该概念相关的段落）:
{excerpt}

## 已知的相关页面（用于 wikilink）
{related_pages}

直接输出完整 Markdown，不要用 ``` 代码块包裹，不要任何解释。"""


def find_excerpt(report: str, keyword: str, chars: int = 800) -> str:
    idx = report.lower().find(keyword.lower())
    if idx == -1:
        return report[:chars]
    start = max(0, idx - 200)
    return report[start:start + chars]


def call2_generate_page(ptype: str, info: dict, report: str, related_pages: str,
                        run_id: str, analysis_file: str) -> tuple:
    if ptype == "source":
        prompt = SOURCE_PROMPT.format(
            report=report[:4000],
            title=info["title"], slug=info["slug"],
            run_id=run_id, analysis_file=analysis_file,
            related_pages=related_pages
        )
    elif ptype == "entity":
        prompt = ENTITY_PROMPT.format(
            name=info["name"],
            excerpt=find_excerpt(report, info["name"]),
            related_pages=related_pages,
            analysis_file=analysis_file
        )
    else:  # concept
        prompt = CONCEPT_PROMPT.format(
            name=info["name"],
            excerpt=find_excerpt(report, info["name"]),
            related_pages=related_pages,
            analysis_file=analysis_file
        )
    text, pt, ct = call_llm(prompt, max_tokens=6000)
    # Post-process: ensure frontmatter has proper --- markers
    text = text.strip()
    if not text.startswith('---'):
        # LLM forgot opening ---, add it
        text = '---\n' + text
    # Check for closing ---
    lines = text.split('\n')
    closing_count = sum(1 for l in lines if l.strip() == '---')
    if closing_count < 2:
        # Find where frontmatter ends (before first ## or blank-line-then-##)
        for i, line in enumerate(lines):
            if i > 0 and line.startswith('##'):
                # Insert --- before this line
                lines.insert(i, '---')
                text = '\n'.join(lines)
                break
            elif i > 0 and line.strip() == '' and i+1 < len(lines) and lines[i+1].startswith('##'):
                lines.insert(i, '---')
                text = '\n'.join(lines)
                break
    return text.strip(), pt, ct


# ── Call 3：图谱连通性审查 ─────────────────────────────────────────────────────

REVIEW_PROMPT = """你是知识图谱质量审查员。检查以下新生成的 wiki 页面之间的连通性。

## 新生成的页面清单
{page_list}

## 任务
找出明显缺失的 wikilink（A 提到了 B 但没有链接到 B）。
每条建议格式：{{页面文件名, 应添加的 [[wikilink]], 原因}}

输出 JSON 数组（最多10条，只列最重要的）：
[{{"file": "xxx.md", "add_link": "[[概念名]]", "reason": "..."}}]

如果连通性已经足够好，输出空数组 []。"""


def call3_review(pages: dict) -> tuple:
    page_list = "\n".join([f"- {fname}: {content[:200]}..." for fname, content in pages.items()])
    prompt = REVIEW_PROMPT.format(page_list=page_list)
    print("  [Call 3] 图谱连通性审查...")
    text, pt, ct = call_llm(prompt, max_tokens=2000)
    try:
        suggestions = extract_json(text)
        if not isinstance(suggestions, list):
            suggestions = []
    except:
        suggestions = []
    print(f"    → {len(suggestions)} 条补链建议 | tokens: {pt}+{ct}")
    return suggestions, pt, ct


def apply_link_suggestions(wiki_path: Path, suggestions: list, pages: dict):
    for s in suggestions:
        fname = s.get("file", "")
        link = s.get("add_link", "")
        if not fname or not link:
            continue
        # 在对应类型目录中查找文件
        for subdir in ["sources", "entities", "concepts"]:
            fpath = wiki_path / "wiki" / subdir / fname
            if fpath.exists():
                content = fpath.read_text(encoding="utf-8")
                if link not in content:
                    content += f"\n\n<!-- 图谱审查补充 -->\n相关：{link}\n"
                    fpath.write_text(content, encoding="utf-8")
                    print(f"    → 补链: {fname} ← {link}")
                break


# ── 幂等查重工具 ─────────────────────────────────────────────────────────────────

_TRACKING_PARAMS = {"si", "utm_source", "utm_medium", "utm_campaign",
                    "utm_term", "utm_content", "ref", "feature", "mc_cid"}


def _normalize_url(url: str) -> str:
    from urllib.parse import urlparse, urlencode, parse_qs, urlunparse
    try:
        p = urlparse(url)
        qs = {k: v for k, v in parse_qs(p.query).items()
              if k.lower() not in _TRACKING_PARAMS}
        return urlunparse(p._replace(query=urlencode(qs, doseq=True)))
    except Exception:
        return url


def _load_source_url_from_context(wiki_path: Path) -> str:
    """从 pipeline-context.json 数据总线读取 source_url。
    这是唯一正确的读取方式——不感知 source_type，不扫描 frontmatter。
    """
    ctx_file = wiki_path / "raw" / "pipeline-context.json"
    if ctx_file.exists():
        try:
            return json.loads(ctx_file.read_text()).get("source_url", "")
        except Exception:
            pass
    return ""


def _find_wiki_page_by_url(wiki_path: Path, source_url: str) -> Path | None:
    """在 wiki/sources/ 下找 source_url frontmatter 匹配的已有页面。"""
    if not source_url:
        return None
    normalized = _normalize_url(source_url)
    sources_dir = wiki_path / "wiki" / "sources"
    if not sources_dir.exists():
        return None
    for f in sources_dir.glob("*.md"):
        try:
            lines = f.read_text(encoding="utf-8").splitlines()
            in_fm = False
            for line in lines:
                if line.strip() == "---":
                    in_fm = not in_fm
                    continue
                if in_fm and line.startswith("source_url:"):
                    existing = line.split(":", 1)[1].strip()
                    if _normalize_url(existing) == normalized:
                        return f
                    break
        except Exception:
            continue
    return None


# ── 主流程 ─────────────────────────────────────────────────────────────────────


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--wiki-path", required=True)
    parser.add_argument("--run-id", required=True)
    parser.add_argument("--before-sha", default="")
    parser.add_argument("--sha", default="HEAD")
    parser.add_argument("--git-sync", action="store_true", help="开头自动 git fetch+reset --hard")
    parser.add_argument("--git-push", action="store_true", help="结尾自动 git add+commit+push")
    parser.add_argument("--analysis-dir", default="raw/notebooklm-analysis",
                        help="分析文件目录，相对于 wiki-path（默认 raw/notebooklm-analysis）")
    args = parser.parse_args()

    wiki_path = Path(args.wiki_path)
    run_id = args.run_id
    start_time = datetime.now(timezone.utc)

    # ── git sync（可选）──
    if args.git_sync:
        import subprocess
        print("[v3] git sync: fetch + reset --hard origin/main ...")
        r = subprocess.run(
            ["git", "fetch", "origin", "main"],
            cwd=wiki_path, capture_output=True, text=True
        )
        subprocess.run(
            ["git", "checkout", "main"],
            cwd=wiki_path, capture_output=True, text=True
        )
        subprocess.run(
            ["git", "reset", "--hard", "origin/main"],
            cwd=wiki_path, capture_output=True, text=True
        )
        print(f"[v3] git sync done")

    # 找分析报告
    analysis_dir = wiki_path / args.analysis_dir
    reports = [f for f in analysis_dir.glob("*.md") if f.name != ".gitkeep"]
    if not reports:
        print("无分析报告可处理，退出")
        sys.exit(0)

    print(f"[v3] 处理 {len(reports)} 份报告，run_id={run_id}")

    # ── 数据契约：优先从 pipeline-context.json 读 output_files 过滤本次报告 ──
    ctx_file = wiki_path / "raw" / "pipeline-context.json"
    _ctx_pre = {}
    if ctx_file.exists():
        try:
            _ctx_pre = json.loads(ctx_file.read_text())
        except Exception:
            pass
    _output_files = _ctx_pre.get("stage_b", {}).get("output_files", [])
    if _output_files:
        _allowed = {Path(f).name for f in _output_files if f.endswith(".md")}
        filtered = [r for r in reports if r.name in _allowed]
        if filtered:
            print(f"  [契约] 依 pipeline-context output_files 过滤：{len(filtered)}/{len(reports)} 份")
            reports = filtered

    # 处理前：拍 wiki/ 快照，用于 diff 找本次新增页面
    _wiki_dir = wiki_path / "wiki"
    _snapshot_before = {
        str(f.relative_to(wiki_path))
        for f in _wiki_dir.rglob("*.md") if f.name != ".gitkeep"
    } if _wiki_dir.exists() else set()

    # ── 幂等查重：唯一数据来源是 pipeline-context.json ─────────────────────
    # 设计原则：不感知 source_type，不扫描 frontmatter，不依赖文件名
    # 适用所有 pipeline（现有/新建/任意 source_type）
    ctx_source_url = _load_source_url_from_context(wiki_path)
    existing_page = _find_wiki_page_by_url(wiki_path, ctx_source_url) if ctx_source_url else None

    new_reports = []
    update_reports = []

    for rf in reports:
        if existing_page:
            print(f"  更新 {rf.name} → {existing_page.name}（pipeline-context source_url 匹配）")
            update_reports.append((rf, existing_page))
        else:
            # 兜底：文件名查重（向后兼容无 pipeline-context 的旧触发路径）
            source_path = wiki_path / "wiki" / "sources" / (rf.stem + ".md")
            if source_path.exists():
                print(f"  更新 {rf.name} → {source_path.name}（文件名兜底）")
                update_reports.append((rf, source_path))
            else:
                new_reports.append(rf)

    all_reports = new_reports + [r for r, _ in update_reports]
    if not all_reports:
        print("所有报告均已是最新，无需处理。")
        sys.exit(0)
    print(f"  新建: {len(new_reports)} 份，更新: {len(update_reports)} 份")
    reports = all_reports

    total_calls = 0
    total_pt = total_ct = 0
    pages_created = 0
    all_generated = {}  # fname → content

    for report_file in reports:
        report_content = report_file.read_text(encoding="utf-8")
        analysis_filename = report_file.name
        print(f"\n报告: {analysis_filename}")

        existing_wiki = read_existing_wiki(wiki_path)

        # ── Call 1 ──
        manifest, pt, ct = call1_extract(report_content, existing_wiki)
        total_calls += 1; total_pt += pt; total_ct += ct

        source_info = manifest.get("source", {})
        entities = [e for e in manifest.get("entities", []) if e.get("action") == "new"]
        concepts = [c for c in manifest.get("concepts", []) if c.get("action") == "new"]

        print(f"  去重后：entities {len(entities)} 新建, concepts {len(concepts)} 新建")

        # 构建 related_pages 上下文（供 Call 2 使用）
        all_names = (
            [source_info.get("title", "")] +
            [e["name"] for e in entities] +
            [c["name"] for c in concepts]
        )
        related_pages = "\n".join([f"- [[{n}]]" for n in all_names if n])

        # ── Call 2：Source 页 ──
        if source_info.get("slug"):
            print(f"  [Call 2] 生成 source: {source_info['title']}")
            content, pt, ct = call2_generate_page(
                "source", source_info, report_content, related_pages,
                run_id, analysis_filename
            )
            total_calls += 1; total_pt += pt; total_ct += ct
            slug = slugify(source_info["slug"])
            fpath = wiki_path / "wiki" / "sources" / f"{slug}.md"
            fpath.parent.mkdir(parents=True, exist_ok=True)
            # 注入 video_url（从 pipeline-context.json 读取）
            if "video_url:" not in content:
                ctx_file = wiki_path / "raw" / "pipeline-context.json"
                try:
                    import json as _json
                    urls = _json.loads(ctx_file.read_text()).get("stage_b", {}).get("processed_urls", [])
                    if urls:
                        content = content.replace("type: source", f"type: source\nvideo_url: {urls[0]}", 1)
                except Exception:
                    pass
            fpath.write_text(content, encoding="utf-8")
            all_generated[fpath.name] = content
            pages_created += 1
            print(f"    → {fpath.name} ({len(content)} chars)")

        # ── Call 2：Entity 页 ──
        for entity in entities:
            print(f"  [Call 2] 生成 entity: {entity['name']}")
            content, pt, ct = call2_generate_page(
                "entity", entity, report_content, related_pages, run_id, analysis_filename
            )
            total_calls += 1; total_pt += pt; total_ct += ct
            slug = slugify(entity["slug"] or entity["name"])
            fpath = wiki_path / "wiki" / "entities" / f"{slug}.md"
            fpath.parent.mkdir(parents=True, exist_ok=True)
            fpath.write_text(content, encoding="utf-8")
            all_generated[fpath.name] = content
            pages_created += 1
            print(f"    → {fpath.name} ({len(content)} chars)")

        # ── Call 2：Concept 页 ──
        for concept in concepts:
            print(f"  [Call 2] 生成 concept: {concept['name']}")
            content, pt, ct = call2_generate_page(
                "concept", concept, report_content, related_pages, run_id, analysis_filename
            )
            total_calls += 1; total_pt += pt; total_ct += ct
            slug = slugify(concept["slug"] or concept["name"])
            fpath = wiki_path / "wiki" / "concepts" / f"{slug}.md"
            fpath.parent.mkdir(parents=True, exist_ok=True)
            fpath.write_text(content, encoding="utf-8")
            all_generated[fpath.name] = content
            pages_created += 1
            print(f"    → {fpath.name} ({len(content)} chars)")

    # ── Call 3：图谱连通性审查 ──
    if all_generated:
        suggestions, pt, ct = call3_review(all_generated)
        total_calls += 1; total_pt += pt; total_ct += ct
        apply_link_suggestions(wiki_path, suggestions, all_generated)

    # ── 生成 wiki/mindmaps/ 脑图（含 wikilinks，不修改 raw/）──
    wiki_mindmaps_dir = wiki_path / "wiki" / "mindmaps"
    wiki_mindmaps_dir.mkdir(parents=True, exist_ok=True)

    entity_links  = [f"[[{Path(f).stem}]]" for f in all_generated if (wiki_path / "wiki" / "entities" / f).exists()]
    concept_links = [f"[[{Path(f).stem}]]" for f in all_generated if (wiki_path / "wiki" / "concepts" / f).exists()]
    source_links  = [f"[[{Path(f).stem}]]" for f in all_generated if (wiki_path / "wiki" / "sources"  / f).exists()]

    for report_file in new_reports:
        # .canvas 优先，fallback 到 .json（两种格式均为 nodes/edges 结构）
        canvas_file = wiki_path / "raw" / "notebooklm-mindmaps" / (report_file.stem + ".canvas")
        if not canvas_file.exists():
            canvas_file = wiki_path / "raw" / "notebooklm-mindmaps" / (report_file.stem + ".json")
        if not canvas_file.exists():
            continue
        try:
            canvas = json.loads(canvas_file.read_text(encoding="utf-8"))
            nodes_map = {n["id"]: n for n in canvas.get("nodes", [])}
            edges = canvas.get("edges", [])
            all_targets = {e["toNode"] for e in edges}
            roots = [n["id"] for n in canvas["nodes"] if n["id"] not in all_targets]
            if not roots:
                continue

            root_label = nodes_map[roots[0]].get("text", report_file.stem)

            def build_children(node_id, indent=2):
                result = ""
                for e in edges:
                    if e["fromNode"] == node_id:
                        child = nodes_map.get(e["toNode"], {})
                        label = child.get("text", "").replace('"', "'")
                        result += "  " * indent + label + "\n"
                        result += build_children(e["toNode"], indent + 1)
                return result

            mermaid_body = f"  root(({root_label}))\n" + build_children(roots[0])

            wikilinks_section = "## 与 Wiki 的链接\n\n"
            if source_links:
                wikilinks_section += f"- 来源：{' '.join(source_links)}\n"
            if entity_links:
                wikilinks_section += f"- 实体：{' '.join(entity_links)}\n"
            if concept_links:
                wikilinks_section += f"- 概念：{' '.join(concept_links)}\n"

            content = (
                f"---\n"
                f"title: {report_file.stem} 脑图\n"
                f"type: mindmap\n"
                f"tags: [mindmap]\n"
                f"summary: {root_label} 知识结构脑图\n"
                f"source: raw/notebooklm-mindmaps/{canvas_file.name}\n"
                f"created: {today()}\n"
                f"run_id: {run_id}\n"
                f"---\n\n"
                f"## 图谱（Obsidian 预览中打开）\n\n"
                f"```mermaid\n"
                f"mindmap\n"
                f"{mermaid_body}"
                f"```\n\n"
                f"{wikilinks_section}"
            )

            out_path = wiki_mindmaps_dir / (report_file.stem + ".md")
            out_path.write_text(content, encoding="utf-8")
            pages_created += 1
            print(f"  ✅ wiki/mindmaps/{out_path.name}")
        except Exception as e:
            print(f"  ⚠️  脑图生成失败 {report_file.stem}: {e}")

    # ── 更新 index.md ──
    index_lines = [
        f"# YouTube Video Research Wiki",
        f"Last updated: {today()}",
        f"Total pages: {pages_created}",
        "",
        "## Sources",
    ]
    for f in (wiki_path / "wiki" / "sources").glob("*.md"):
        if f.name != ".gitkeep":
            index_lines.append(f"- [[{f.stem}]]")
    index_lines.append("\n## Entities")
    for f in (wiki_path / "wiki" / "entities").glob("*.md"):
        if f.name != ".gitkeep":
            index_lines.append(f"- [[{f.stem}]]")
    index_lines.append("\n## Concepts")
    for f in (wiki_path / "wiki" / "concepts").glob("*.md"):
        if f.name != ".gitkeep":
            index_lines.append(f"- [[{f.stem}]]")
    index_lines.append("\n## Mindmaps")
    for f in (wiki_path / "wiki" / "mindmaps").glob("*.md"):
        if f.name != ".gitkeep":
            index_lines.append(f"- [[{f.stem}]]")
    (wiki_path / "index.md").write_text("\n".join(index_lines), encoding="utf-8")

    # ── 写 run log ──
    end_time = datetime.now(timezone.utc)
    duration = int((end_time - start_time).total_seconds())
    run_log = {
        "run_id": run_id, "stage": "stage_c_v3",
        "start_time": start_time.strftime("%Y-%m-%dT%H:%M:%SZ"),
        "end_time": end_time.strftime("%Y-%m-%dT%H:%M:%SZ"),
        "duration_s": duration,
        "llm_calls": total_calls,
        "prompt_tokens": total_pt,
        "completion_tokens": total_ct,
        "total_tokens": total_pt + total_ct,
        "pages_created": pages_created,
        "status": "success"
    }
    log_dir = wiki_path / "logs" / "webhook-runs"
    log_dir.mkdir(parents=True, exist_ok=True)
    (log_dir / f"{run_id}.md").write_text(
        f"---\n{json.dumps(run_log, ensure_ascii=False, indent=2)}\n---\n"
        f"Pages: {pages_created} | LLM calls: {total_calls} | Tokens: {total_pt+total_ct} | Time: {duration}s",
        encoding="utf-8"
    )

    # 写 pipeline-context.json（供 Stage D 读取）
    # 以磁盘实际文件数为准（比运行时计数更准确）
    def count_md(d): return len([f for f in d.glob("*.md") if f.name != ".gitkeep"]) if d.exists() else 0
    actual_sources     = count_md(wiki_path / "wiki" / "sources")
    actual_entities    = count_md(wiki_path / "wiki" / "entities")
    actual_concepts    = count_md(wiki_path / "wiki" / "concepts")
    actual_comparisons = count_md(wiki_path / "wiki" / "comparisons")
    actual_mindmaps    = count_md(wiki_path / "wiki" / "mindmaps")
    actual_total       = actual_sources + actual_entities + actual_concepts + actual_comparisons + actual_mindmaps

    ctx_file = wiki_path / "raw" / "pipeline-context.json"
    ctx = {}
    if ctx_file.exists():
        try:
            ctx = json.loads(ctx_file.read_text())
        except Exception:
            pass
    # diff：本次新增的 wiki 页面路径（相对 wiki_local_path）
    _snapshot_after = {
        str(f.relative_to(wiki_path))
        for f in _wiki_dir.rglob("*.md") if f.name != ".gitkeep"
    } if _wiki_dir.exists() else set()
    new_file_paths = sorted(_snapshot_after - _snapshot_before)

    ctx["stage_c"] = {
        "run_id": run_id,
        "start_time": start_time.strftime("%Y-%m-%dT%H:%M:%SZ"),
        "end_time": end_time.strftime("%Y-%m-%dT%H:%M:%SZ"),
        "duration_s": duration,
        "llm_calls": total_calls,
        "pages_created_total": actual_total,
        "pages_new_this_run": len(new_file_paths),
        "file_paths": new_file_paths,          # Stage D 用来拼 GitHub 链接
        "sources": actual_sources,
        "entities": actual_entities,
        "concepts": actual_concepts,
        "comparisons": actual_comparisons,
        "prompt_tokens": total_pt,
        "completion_tokens": total_ct,
        "status": "success"
    }
    ctx_file.write_text(json.dumps(ctx, ensure_ascii=False, indent=2))

    # ── git push（可选，含重试机制）──
    if args.git_push:
        import subprocess, time
        print("[v3] git push: add + commit + push ...")
        subprocess.run(["git", "add", "-A"], cwd=wiki_path)
        # pipeline_id 从 pipeline-context.json 读取（由 Stage B 写入）
        pipeline_id = ctx.get("pipeline_id", "")
        pipe_tag = f" [pipe:{pipeline_id}]" if pipeline_id else ""
        msg = f"chore: stage-c done{pipe_tag} [run:{run_id}]"
        r = subprocess.run(
            ["git", "commit", "-m", msg],
            cwd=wiki_path, capture_output=True, text=True
        )
        if r.returncode != 0:
            print(f"[v3] nothing to commit")
        else:
            pushed = False
            for attempt in range(1, 4):  # 最多重试 3 次
                push = subprocess.run(
                    ["git", "push", "origin", "main"],
                    cwd=wiki_path, capture_output=True, text=True
                )
                if push.returncode == 0:
                    print(f"[v3] git push ✅ (attempt {attempt})")
                    pushed = True
                    break
                print(f"[v3] push attempt {attempt} failed: {push.stderr[:150]}")
                # rebase 后重试（处理 non-fast-forward）
                subprocess.run(
                    ["git", "pull", "--rebase", "origin", "main"],
                    cwd=wiki_path, capture_output=True, text=True
                )
                time.sleep(3)
            if not pushed:
                print(f"[v3] git push ❌ after 3 attempts")
                sys.exit(1)

    print(f"\n{'='*50}")
    print(f"[v3] 完成 | pages={pages_created} | llm_calls={total_calls} | tokens={total_pt+total_ct} | {duration}s")
    print(json.dumps(run_log, ensure_ascii=False))


if __name__ == "__main__":
    main()
